class Store:
    def __init__(self):
        self.customers = []
    def add(self, c):
        self.customers.append(c)
    def sale(self):
        for c in self.customers:
            c.notify()

class Shopper:
    def notify(self):
        print("Buying now!")

shop = Store()
shop.add(Shopper())
shop.add(Shopper())
shop.sale()

class WeatherStation:
    def __init__(self):
        self.screens = []
    def update(self, temp):
        for screen in self.screens:
            screen(temp)

class Display:
    def show(self, temp):
        print(temp)

station = WeatherStation()
station.screens.append(Display())
station.update(25)

