class Alarm:
    def __init__(self):
        self.listeners = []
    def trigger(self):
        for listener in self.listeners:
            listener.sound()

class Siren:
    def sound(self): print("WEE WOO")

class Phone:
    def sound(self): print("Beep beep")

alarm = Alarm()
alarm.listeners = [Siren(), Phone()]
alarm.trigger()

