practice_tasks.solution:
class System:
    def __init__(self):
        self.obs = []
    def error(self, msg):
        for o in self.obs: o.log(msg)

class FileLogger:
    def log(self, msg): print(f"File: {msg}")

class EmailLogger:
    def log(self, msg): print(f"Email: {msg}")

system = System()
system.obs.append(FileLogger())
# Subscribe the EmailLogger here
system.obs.append(EmailLogger())

system.error("Disk full")
